using System;
using System.Collections.Generic;
using Contoso.Orders;
using static System.Math;
using Json = System.Text.Json.JsonSerializer;

namespace Contoso.Reports;

public class OrderExporter
{
    #region Fields
    private readonly IOrderService _orderService;
    #endregion

    #region Constructor
    public OrderExporter(IOrderService orderService)
    {
        _orderService = orderService ?? throw new ArgumentNullException(nameof(orderService));
    }
    #endregion

    #region PublicMethods
    public string Export(IReadOnlyList<Order> orders)
    {
        if (orders is null)
        {
            throw new ArgumentNullException(nameof(orders));
        }

        var rounded = new List<decimal>();
        foreach (var order in orders)
        {
            rounded.Add(Round(order.Total, 2));
        }

        return Json.Serialize(rounded);
    }
    #endregion
}
